#include <bits/stdc++.h>
using namespace std;

int n, fullMask;
int forbid[8];

long long dfs(int r, int cols, int d1, int d2) {
    if (r == n) return 1;
    long long total = 0;
    int avail = fullMask & ~(cols | d1 | d2 | forbid[r]);
    while (avail) {
        int b = avail & -avail;
        avail -= b;
        total += dfs(r + 1, cols | b, ((d1 | b) << 1) & fullMask, (d2 | b) >> 1);
    }
    return total;
}

int main() {
    cin >> n;
    fullMask = (1 << n) - 1;
    for (int i = 0; i < n; i++) {
        string row;
        cin >> row;
        forbid[i] = 0;
        for (int j = 0; j < n; j++)
            if (row[j] == '#') forbid[i] |= 1 << j;
    }
    cout << dfs(0, 0, 0, 0) << '\n';
    return 0;
}

