    vector<pair<int, int>> st(n);
    for (auto &s : st) cin >> s.first >> s.second;
    sort(st.begin(), st.end());
    st.push_back({D, 0});

    int fuel = F, pos = 0, stops = 0;
    priority_queue<int> heap;  // 已經過但尚未使用的加油量，取最大者
    for (auto &s : st) {
        int need = s.first - pos;
        while (fuel < need) {
            if (heap.empty()) {
                cout << -1 << '\n';
                return 0;
            }
            fuel += heap.top();
            heap.pop();
            stops++;
        }
        fuel -= need;
        pos = s.first;
        heap.push(s.second);
    }
    cout << stops << '\n';
    return 0;
}

