                    total += go(pos + 1, -1, nt, False)   # 仍是前導零
                else:
                    total += go(pos + 1, d, nt, True)     # 第一個非零數字
            elif abs(d - prev) >= 2:
                total += go(pos + 1, d, nt, True)
        return total

