import sys

MOD = 10**9 + 7


def divisors_with_phi(n):
    """回傳 n 的所有 (因數 d, φ(d))。"""
    divs = [(1, 1)]
    p = 2
    while p * p <= n:
        if n % p == 0:
            e = 0
            while n % p == 0:
                n //= p
                e += 1
            new = []
            for d, ph in divs:
                pk = 1
                for t in range(e + 1):
                    if t == 0:
                        new.append((d, ph))
                    else:
                        pk *= p
                        new.append((d * pk, ph * (pk - pk // p)))
            divs = new
        p += 1
    if n > 1:
        divs = divs + [(d * n, ph * (n - 1)) for d, ph in divs]
    return divs


def solve(n, k):
    rot = 0
    for d, ph in divisors_with_phi(n):
        rot = (rot + ph % MOD * pow(k, n // d, MOD)) % MOD
    if n % 2 == 1:
        refl = n % MOD * pow(k, (n + 1) // 2, MOD) % MOD
    else:
        refl = (n // 2) % MOD * (pow(k, n // 2 + 1, MOD) + pow(k, n // 2, MOD)) % MOD
    return (rot + refl) % MOD * pow(2 * n % MOD, MOD - 2, MOD) % MOD


def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    out = []
    for i in range(t):
        n, k = int(data[1 + 2 * i]), int(data[2 + 2 * i])
        out.append(str(solve(n, k)))
    print("\n".join(out))


