        if (n % p == 0) {
            int e = 0;
            while (n % p == 0) {
                n /= p;
                e++;
            }
            vector<pair<ll, ll>> nxt;
            for (auto& dp : divs) {
                ll pk = 1;
                for (int t = 0; t <= e; t++) {
                    if (t == 0) {
                        nxt.push_back(dp);
                    } else {
                        pk *= p;
                        nxt.push_back({dp.first * pk, dp.second * (pk - pk / p)});
                    }
                }
            }
            divs = nxt;
        }
    }
    if (n > 1) {
        size_t sz = divs.size();
        for (size_t i = 0; i < sz; i++)
            divs.push_back({divs[i].first * n, divs[i].second * (n - 1)});
    }
